    varying vec3 vCol, vN, vW;
    void main() {
      vec3 n = normalize(vN);

      float ndl = dot(n, uSunDir);
      float wrap = 0.000;
      vec3 L = ambient(n) + uSunCol * max((ndl + wrap) / (1.0 + wrap), 0.0);
